-- =====================================================================
--  File : 08a_raw_data.sql
--  Kya  : academicaid.in ki teeno branches (CSE, ECE, EE) ki saari files
--         ki list - KACHCHA data. Ye ek "staging" table me jaata hai.
--  Kahan se: academicaid ke har subject link ke Google Drive folder ko
--         andar tak khol ke, 2026-11-06 ko.
--  Run  : INCIPIT par, poori file Ctrl+A, Ctrl+Enter. Phir 08b chalana.
--
--  Har row = ek file + ek subject. (2 files do subjects ki hain, isliye
--  1009 files ki 1011 rows hain.)
--
--  Columns:
--    drive_id       Google Drive ki file ID - isi se link banega
--    subject_short  academicaid ke kis subject link ke andar mili
--    file_name      Drive par file ka asli naam
--    folder_path    subject folder ke andar ka raasta, jaise "3.PYQS / 1.MID SEM"
--    title          file_name ka saaf kiya hua roop
--    resource_type  folder / naam se andaza (PYQS folder -> PYQ, BOOKS -> BOOK ...)
--    academic_year  naam ya folder me 2015-2039 jaisa saal mila to
--    exam_type      sirf PYQ ke liye: naam/folder me "mid" -> MID,
--                   "end"/"sem"/dec/may... -> END, warna NULL
--
--  Note: Oracle-tools me "&" kabhi-kabhi variable samjha jaata hai,
--        isliye naamon me "&" ko "and" likha gaya hai.
-- =====================================================================

CREATE TABLE import_files (
    drive_id       VARCHAR2(80)        NOT NULL,
    subject_short  VARCHAR2(20)        NOT NULL,
    file_name      VARCHAR2(500 CHAR),
    folder_path    VARCHAR2(1000 CHAR),
    title          VARCHAR2(300 CHAR),
    resource_type  VARCHAR2(10),
    academic_year  NUMBER(4),
    exam_type      VARCHAR2(3)
);

